diff --git a/packages/plugin-import-export/src/utilities/buildDisabledFieldRegex.ts b/packages/plugin-import-export/src/utilities/buildDisabledFieldRegex.ts
new file mode 100644
index 00000000000..41e44ad72e1
--- /dev/null
+++ b/packages/plugin-import-export/src/utilities/buildDisabledFieldRegex.ts
@@ -0,0 +1,13 @@
+/**
+ * Builds a RegExp that matches flattened field keys from a given dot-notated path.
+ */
+export const buildDisabledFieldRegex = (path: string): RegExp => {
+  const parts = path.split('.')
+
+  const patternParts = parts.map((part) => {
+    return `${part}(?:_\\d+)?(?:_[^_]+)?`
+  })
+
+  const pattern = `^${patternParts.join('_')}(?:_.*)?$`
+  return new RegExp(pattern)
+}
diff --git a/packages/plugin-import-export/src/utilities/collectDisabledFieldPaths.ts b/packages/plugin-import-export/src/utilities/collectDisabledFieldPaths.ts
new file mode 100644
index 00000000000..8a36140fc10
--- /dev/null
+++ b/packages/plugin-import-export/src/utilities/collectDisabledFieldPaths.ts
@@ -0,0 +1,43 @@
+import { fieldAffectsData } from 'payload/shared'
+
+export const collectDisabledFieldPaths = (fields: any[], path: string[] = []): string[] => {
+  const disabledPaths: string[] = []
+
+  for (const field of fields) {
+    const currentPath = [...path, field.name]
+    const currentPathStr = currentPath.join('.')
+
+    if (fieldAffectsData(field)) {
+      if (field.custom?.['plugin-import-export']?.disabled) {
+        // Push only the parent accessor, and skip collecting subfields
+        disabledPaths.push(currentPathStr)
+        continue // prevent recursion
+      }
+    }
+
+    // Blocks
+    if (field.type === 'blocks' && Array.isArray(field.blocks)) {
+      for (const block of field.blocks) {
+        const blockPath = [...currentPath] // same base as the blocks field
+        disabledPaths.push(...collectDisabledFieldPaths(block.fields, blockPath))
+      }
+    }
+
+    // Recurse into subfields
+    if (field.fields) {
+      disabledPaths.push(...collectDisabledFieldPaths(field.fields, currentPath))
+    }
+
+    // Tabs
+    if (field.type === 'tabs' && Array.isArray(field.tabs)) {
+      for (const tab of field.tabs) {
+        if ('fields' in tab) {
+          const tabPath = tab.name ? [...path, tab.name] : path
+          disabledPaths.push(...collectDisabledFieldPaths(tab.fields, tabPath))
+        }
+      }
+    }
+  }
+
+  return disabledPaths
+}
